CREATE TRIGGER discovery_facebook_identity_source_insert BEFORE INSERT ON discovery_facebook_identity_reads WHEN NOT EXISTS(SELECT 1 FROM discovery_search_hits h WHERE h.id=NEW.search_hit_id AND h.discovery_campaign_id=NEW.discovery_campaign_id AND h.platform=NEW.platform AND h.profile_ref=NEW.profile_ref AND h.source_url=NEW.source_url) BEGIN SELECT RAISE(ABORT,'Facebook identity source mismatch'); END;
CREATE TRIGGER discovery_facebook_identity_source_update BEFORE UPDATE ON discovery_facebook_identity_reads WHEN NEW.search_hit_id!=OLD.search_hit_id OR NEW.discovery_campaign_id!=OLD.discovery_campaign_id OR NEW.platform!=OLD.platform OR NEW.profile_ref!=OLD.profile_ref OR NEW.source_url!=OLD.source_url OR NEW.expected_revision!=OLD.expected_revision OR NEW.call_number!=OLD.call_number OR OLD.status!='reading' BEGIN SELECT RAISE(ABORT,'Facebook identity receipt is immutable'); END;
CREATE TRIGGER discovery_facebook_native_profile_insert BEFORE INSERT ON discovery_profile_reads WHEN NEW.platform='facebook' AND NEW.status='completed' AND json_extract(NEW.native_profile_json,'$.adapter_version') IS '2.0.0' AND NOT EXISTS(SELECT 1 FROM discovery_facebook_identity_reads i JOIN discovery_search_authors a ON a.search_hit_id=i.search_hit_id WHERE i.search_hit_id=NEW.search_hit_id AND i.discovery_campaign_id=NEW.discovery_campaign_id AND i.profile_ref=NEW.profile_ref AND i.expected_revision=NEW.expected_revision AND i.status='completed' AND i.stop_code IS NULL AND i.call_number<NEW.call_number AND json_extract(i.native_identity_json,'$.id') IS NEW.author_id AND a.author_id=NEW.author_id AND a.author_url='https://www.facebook.com/profile.php?id='||NEW.author_id AND json_extract(NEW.native_profile_json,'$.id') IS NEW.author_id AND json_extract(NEW.native_profile_json,'$.profile_url') IS a.author_url AND json_extract(NEW.native_profile_json,'$.evidence_source') IS 'native_profile_header_response' AND lower(json_extract(NEW.native_profile_json,'$.observed_profile_url')) IS lower(rtrim(i.source_url,'/'))) BEGIN SELECT RAISE(ABORT,'Facebook native profile requires source identity'); END;
CREATE TRIGGER discovery_facebook_native_profile_update BEFORE UPDATE ON discovery_profile_reads WHEN NEW.platform='facebook' AND NEW.status='completed' AND json_extract(NEW.native_profile_json,'$.adapter_version') IS '2.0.0' AND NOT EXISTS(SELECT 1 FROM discovery_facebook_identity_reads i JOIN discovery_search_authors a ON a.search_hit_id=i.search_hit_id WHERE i.search_hit_id=NEW.search_hit_id AND i.discovery_campaign_id=NEW.discovery_campaign_id AND i.profile_ref=NEW.profile_ref AND i.expected_revision=NEW.expected_revision AND i.status='completed' AND i.stop_code IS NULL AND i.call_number<NEW.call_number AND json_extract(i.native_identity_json,'$.id') IS NEW.author_id AND a.author_id=NEW.author_id AND a.author_url='https://www.facebook.com/profile.php?id='||NEW.author_id AND json_extract(NEW.native_profile_json,'$.id') IS NEW.author_id AND json_extract(NEW.native_profile_json,'$.profile_url') IS a.author_url AND json_extract(NEW.native_profile_json,'$.evidence_source') IS 'native_profile_header_response' AND lower(json_extract(NEW.native_profile_json,'$.observed_profile_url')) IS lower(rtrim(i.source_url,'/'))) BEGIN SELECT RAISE(ABORT,'Facebook native profile requires source identity'); END;
CREATE TRIGGER discovery_facebook_original_immutable BEFORE UPDATE ON discovery_facebook_original_attempts WHEN OLD.status!='reading' OR NEW.search_hit_id!=OLD.search_hit_id OR NEW.discovery_campaign_id!=OLD.discovery_campaign_id OR NEW.profile_ref!=OLD.profile_ref OR NEW.author_id!=OLD.author_id OR NEW.source_url!=OLD.source_url OR NEW.expected_revision!=OLD.expected_revision OR NEW.call_number!=OLD.call_number BEGIN SELECT RAISE(ABORT,'Facebook original attempt is immutable'); END;
CREATE TRIGGER discovery_facebook_original_source BEFORE INSERT ON discovery_facebook_original_attempts WHEN NOT EXISTS(SELECT 1 FROM discovery_facebook_content_targets t JOIN discovery_profile_reads p ON p.search_hit_id=t.search_hit_id JOIN discovery_content_reads c ON c.search_hit_id=t.search_hit_id WHERE t.search_hit_id=NEW.search_hit_id AND t.discovery_campaign_id=NEW.discovery_campaign_id AND t.profile_ref=NEW.profile_ref AND t.author_id=NEW.author_id AND t.expected_revision=NEW.expected_revision AND t.status='completed' AND t.stop_code IS NULL AND t.call_number<NEW.call_number AND p.status='completed' AND json_extract(p.native_profile_json,'$.adapter_version') IS '2.0.0' AND c.platform='facebook' AND c.discovery_campaign_id=NEW.discovery_campaign_id AND c.profile_ref=NEW.profile_ref AND c.author_id=NEW.author_id AND c.expected_revision=NEW.expected_revision AND c.status='reading' AND c.source_url=NEW.source_url AND c.call_number=NEW.call_number AND EXISTS(SELECT 1 FROM json_each(t.source_urls_json) l WHERE l.value=NEW.source_url)) BEGIN SELECT RAISE(ABORT,'Facebook original source mismatch'); END;
CREATE TRIGGER discovery_identity_reviews_no_update BEFORE UPDATE ON discovery_identity_reviews BEGIN SELECT RAISE(ABORT, 'identity_review_is_immutable'); END;
CREATE TRIGGER discovery_manual_approval_immutable BEFORE UPDATE ON discovery_manual_approvals BEGIN SELECT RAISE(ABORT, 'manual_approval_is_immutable'); END;
CREATE TRIGGER prevent_creator_contact_route_dependency_cycle_insert BEFORE INSERT ON creator_contact_route_dependencies WHEN EXISTS ( WITH RECURSIVE descendants(route_id) AS ( SELECT child_contact_route_id FROM creator_contact_route_dependencies WHERE parent_contact_route_id = NEW.child_contact_route_id UNION SELECT dependency.child_contact_route_id FROM creator_contact_route_dependencies dependency JOIN descendants ON dependency.parent_contact_route_id = descendants.route_id ) SELECT 1 FROM descendants WHERE route_id = NEW.parent_contact_route_id ) BEGIN SELECT RAISE(ABORT, 'contact route dependency cycle'); END;
CREATE TRIGGER prevent_creator_contact_route_dependency_cycle_update BEFORE UPDATE OF parent_contact_route_id, child_contact_route_id ON creator_contact_route_dependencies WHEN EXISTS ( WITH RECURSIVE descendants(route_id) AS ( SELECT child_contact_route_id FROM creator_contact_route_dependencies WHERE parent_contact_route_id = NEW.child_contact_route_id AND NOT ( parent_contact_route_id = OLD.parent_contact_route_id AND child_contact_route_id = OLD.child_contact_route_id ) UNION SELECT dependency.child_contact_route_id FROM creator_contact_route_dependencies dependency JOIN descendants ON dependency.parent_contact_route_id = descendants.route_id WHERE NOT ( dependency.parent_contact_route_id = OLD.parent_contact_route_id AND dependency.child_contact_route_id = OLD.child_contact_route_id ) ) SELECT 1 FROM descendants WHERE route_id = NEW.parent_contact_route_id ) BEGIN SELECT RAISE(ABORT, 'contact route dependency cycle'); END;
CREATE TRIGGER prevent_email_claim_during_mailbox_credential_deletion BEFORE INSERT ON idempotency_records WHEN NEW.mailbox_ref_id IS NOT NULL AND NEW.action IN ('email_send','manual_email_send','email_draft_send') AND EXISTS ( SELECT 1 FROM mailbox_credential_deletion_guards WHERE mailbox_ref_id = NEW.mailbox_ref_id ) BEGIN SELECT RAISE(ABORT, 'mailbox credential deletion is in progress'); END;
CREATE TRIGGER prevent_shared_creator_contact_locator_insert BEFORE INSERT ON creator_contact_routes WHEN NOT EXISTS ( SELECT 1 FROM creator_contact_routes existing WHERE existing.locator_id = NEW.locator_id AND existing.creator_id = NEW.creator_id ) AND EXISTS ( SELECT 1 FROM creator_contact_routes existing WHERE existing.locator_id = NEW.locator_id AND existing.creator_id != NEW.creator_id ) BEGIN SELECT RAISE(ABORT, 'contact route already belongs to another Creator'); END;
CREATE TRIGGER prevent_shared_creator_contact_locator_update BEFORE UPDATE OF creator_id, locator_id ON creator_contact_routes WHEN (NEW.creator_id != OLD.creator_id OR NEW.locator_id != OLD.locator_id) AND EXISTS ( SELECT 1 FROM creator_contact_routes existing WHERE existing.locator_id = NEW.locator_id AND existing.creator_id != NEW.creator_id AND existing.id != OLD.id ) BEGIN SELECT RAISE(ABORT, 'contact route already belongs to another Creator'); END;
